def build_prompt(report):
    return [
        {"role": "system",
         "content": "You are a musculoskeletal radiologist extracting structured findings from "
                    "knee MRI reports. You read the report in its ORIGINAL language and never "
                    "translate before deciding. You output only JSON."},
        {"role": "user",
         "content": f"""Read this knee MRI report and decide, for each of twelve findings, what the
report states. Work in the report's own language.

TWELVE FINDINGS
{DEFINITIONS}

{VOCABULARY}

{SEVERITY}

{ACL_SUB}

STATUS, choose exactly one per finding:
  positive       the report asserts the finding is present
  negative       the report EXPLICITLY asserts it is absent, or describes only a repaired/old state
  uncertain      the report hedges (see HEDGING above)
  not_mentioned  the report says nothing about this finding either way

NEGATIVE vs NOT_MENTIONED -- read this twice, it is the distinction most often got wrong.
"negative" means the report contains a sentence DENYING the finding, and you must be able to quote
that sentence: "no fracture", "menisci intact", "sin derrame", "yirtik yok". If the report simply
never discusses the structure, that is "not_mentioned", with empty evidence. Silence is not denial.
A typical knee MRI report discusses only a few of the twelve findings, so MOST findings in MOST
reports are "not_mentioned". If you are about to answer "negative" and cannot quote a denial,
the answer is "not_mentioned".

EVIDENCE: for any status other than not_mentioned, quote the shortest VERBATIM substring of the
report that justifies your decision. Copy it exactly, character for character, from the report. Do
not translate it, do not paraphrase it, do not add ellipses. For not_mentioned use "".

COMPARTMENT: for Medial/Lateral Meniscus and Medial/Lateral OA, state which compartment the
evidence refers to ("medial" or "lateral"); otherwise null.

ACL_SUBSTATUS: for the ACL finding only, add "acl_substatus" with one of the eight values listed
above. For the other eleven findings omit it or use null. Decide the sub-status from what the report
describes, independently of the status you chose.

Also report "report_language" as an ISO 639-1 code.

Output ONLY this JSON, no commentary:
{{"report_language": "xx",
 "findings": [{{"finding": "ACL", "status": "...", "severity": "...", "evidence": "...",
   "compartment": null, "acl_substatus": "..."}}, ... all twelve in the order listed
   above, "acl_substatus" on ACL only ...]}}

REPORT:
{report}"""}]


def norm(s):
    """Whitespace AND Unicode normalisation, applied to both sides of the substring check.

    95% of the Greek reports write MICRO SIGN U+00B5 where Greek small mu U+03BC belongs, and no
    other language in the corpus uses the character at all. They are visually identical, so a model
    copying evidence verbatim will often emit the real mu; without NFKC the substring check would
    reject it and mark most Greek cells invalid for a purely typographic reason. NFKC is applied to
    the report too, so the check is no weaker about content."""
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", str(s or ""))).strip()


def validate(obj, report):
    """Schema validity and the evidence-substring check, which is the anti-confabulation test."""
    problems, cells = [], {}
    if not isinstance(obj, dict) or "findings" not in obj:
        return None, ["no findings key"], ""
    got = {}
    for f in obj.get("findings", []):
        if isinstance(f, dict) and f.get("finding") in LAB:
            got[f["finding"]] = f
    rnorm = norm(report).lower()
    for name in LAB:
        f = got.get(name)
        if f is None:
            problems.append(f"{name}: missing")
            cells[name] = {"status": "invalid", "severity": "unspecified", "evidence": "",
                           "compartment": None, "evidence_ok": False,
                           "acl_substatus": "unspecified" if name == "ACL" else ""}
            continue
        st = str(f.get("status", "")).lower()
        if st not in ("positive", "negative", "uncertain", "not_mentioned"):
            problems.append(f"{name}: bad status {st!r}")
            st = "invalid"
        sev = str(f.get("severity", "unspecified")).lower()
        if sev not in ("none", "trace", "small_mild", "moderate", "large_severe", "unspecified"):
            sev = "unspecified"
        ev = str(f.get("evidence", "") or "")
        ev_ok = True
        if st in ("positive", "negative", "uncertain"):
            ev_ok = bool(ev) and norm(ev).lower() in rnorm
            if not ev_ok:
                problems.append(f"{name}: evidence not a substring")
        comp = f.get("compartment")
        comp = comp if comp in ("medial", "lateral") else None
        acl_sub = ""
        if name == "ACL":
            acl_sub = str(f.get("acl_substatus", "") or "").lower().strip()
            if acl_sub not in ACL_SUB_BINARISE:
                if acl_sub:
                    problems.append(f"ACL: bad acl_substatus {acl_sub!r}")
                acl_sub = "unspecified"
        cells[name] = {"status": st, "severity": sev, "evidence": ev,
                       "compartment": comp, "evidence_ok": ev_ok, "acl_substatus": acl_sub}
    return cells, problems, str(obj.get("report_language", ""))


def parse_json(text):
    t = text.strip()
    t = re.sub(r"^```(?:json)?|```$", "", t, flags=re.M).strip()
    a, b = t.find("{"), t.rfind("}")
    if a < 0 or b <= a:
        return None
    try:
        return json.loads(t[a:b + 1])
    except Exception:
        try:
            return json.loads(re.sub(r",\s*([}\]])", r"\1", t[a:b + 1]))
        except Exception:
            return None


