def select(stage, train, lang):
    """probe: 10 spread over languages. pilot: 200 non-gold stratified + all 58 gold + the
    known-answer cases. full: everything."""
    host = train[train[LAB].notna().all(axis=1)].StudyInstanceUID.astype(str).tolist()
    df = train.copy()
    df["StudyInstanceUID"] = df.StudyInstanceUID.astype(str)
    df = df.merge(lang, on="StudyInstanceUID", how="left")
    df["language"] = df.language.fillna("unassigned")
    if stage == "full":
        # Budget levers, both deterministic and both blind to any model prediction. LANGS keeps only
        # the named families; CAP keeps at most that many studies per family, sampled under SEED.
        # P1 contrasts Turkish/Croatian against English/Dutch and P2 needs Greek and Bulgarian, so
        # a run restricted to those six costs about half the corpus and weakens neither prediction.
        if LANGS:
            df = df[df.language.isin(LANGS)]
            print(f"corpus restricted to {sorted(LANGS)}: {len(df)} studies", flush=True)
        if CAP:
            r2 = np.random.default_rng(SEED)
            keep = []
            for lg, g in df.groupby("language"):
                ids_g = g.StudyInstanceUID.to_numpy()
                keep += (ids_g.tolist() if len(ids_g) <= CAP
                         else r2.choice(ids_g, CAP, replace=False).tolist())
            df = df[df.StudyInstanceUID.isin(keep)]
            print(f"capped at {CAP} studies per language: {len(df)} studies", flush=True)
        return df.StudyInstanceUID.tolist(), {}
    rng = np.random.default_rng(SEED)
    non_gold = df[~df.StudyInstanceUID.isin(host)]
    want = N_PROBE if stage == "probe" else N_PILOT
    groups = [g for _, g in non_gold.groupby("language") if len(g)]
    per = max(1, want // max(len(groups), 1))
    picks = []
    for g in groups:
        take = min(per, len(g))
        picks += rng.choice(g.StudyInstanceUID.to_numpy(), take, replace=False).tolist()
    pool = non_gold[~non_gold.StudyInstanceUID.isin(picks)].StudyInstanceUID.to_numpy()
    if len(picks) < want and len(pool):
        picks += rng.choice(pool, min(want - len(picks), len(pool)), replace=False).tolist()
    extra = {}
    if stage == "pilot":
        for name, (pat, finding, want_status, why) in KNOWN_ANSWER.items():
            m = df[df.Report.astype(str).map(lambda t: bool(
                re.search(pat, unicodedata.normalize("NFKC", str(t)), re.I)))]
            if not len(m):
                print(f"known-answer case {name!r} not found in this corpus -- skipped", flush=True)
                continue
            sid = m.StudyInstanceUID.iloc[0]
            extra[name] = {"study": sid, "finding": finding, "expected_status": want_status,
                           "rule": why}
            picks.append(sid)
        picks += host
    return list(dict.fromkeys(picks)), extra


DIAG = {}


def dump_diag(extra=None):
    """Write diagnostics to a FILE, not just stdout: this kernel's predecessor produced a log
    that never downloaded, and a run that leaves no artefact cannot be debugged."""
    if extra:
        DIAG.update(extra)
    try:
        WORK.mkdir(parents=True, exist_ok=True)
        json.dump(DIAG, open(WORK / f"extract_diag_{PASS_NAME}_{STAGE}.json", "w"),
                  indent=1, default=str)
    except Exception:
        pass


def pip_install(pkg):
    """Quiet install. pip's progress output is suspected of breaking Kaggle's log writer, so
    nothing from it is echoed."""
    import subprocess
    for attempt in range(3):
        r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-input", pkg],
                           capture_output=True, text=True, timeout=2400)
        if r.returncode == 0:
            return True, ""
        if attempt < 2:
            time.sleep(15 * (attempt + 1))
    return False, (r.stderr or "")[-300:]


VLLM_PIN = "vllm==0.30.0"
VLLM_CU_INDEX = "https://download.pytorch.org/whl/cu130"


def vllm_bootstrap():
    """Install vLLM for Kaggle's CURRENT image; return the child's extra env ({} -- none needed).

    HISTORY. The old path used kaggle-vllm==0.2.0, which pinned the September image
    (py3.12 / torch2.10 / cu128). Kaggle moved to py3.13 / torch2.11 / cu128 and kaggle-vllm (whose
    latest release is 0.2.0) cannot follow it -- `bootstrap --strict` refuses the mismatched runtime.
    Probing (kaggle/vllmprobe, 2026-10-04) established the working combination on the new image, whose
    driver 580.178.04 DOES support CUDA 13:
        pip install vllm==0.30.0                                   # pulls torch 2.13+cu130
        pip install -U torchaudio torchvision --extra-index-url cu130   # aligns family -> 2.14.1+cu130
    vLLM then imports and generates at TP=1 and TP=2. A plain `pip install vllm` alone still breaks the
    stack (probe v2: torch goes cu130 while torchaudio stays cu128 -> version-check error); the family
    alignment is what makes it consistent. Unlike the staged kaggle-vllm wheel this is an ordinary
    site-packages install, so the workers need no special PYTHONPATH and the child env is empty.
    """
    import subprocess
    steps = [[VLLM_PIN],
             ["--upgrade", "torchaudio", "torchvision", "--extra-index-url", VLLM_CU_INDEX]]
    for args in steps:
        ok, err = False, ""
        for attempt in range(3):
            r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-input", *args],
                               capture_output=True, text=True, timeout=3600)
            if r.returncode == 0:
                ok = True
                break
            err = (r.stderr or "")[-400:]
            if attempt < 2:
                time.sleep(20 * (attempt + 1))
        DIAG.setdefault("vllm_install", []).append({"args": args, "ok": ok, "err": err})
        dump_diag()
        if not ok:
            raise RuntimeError(f"vLLM install step failed: pip install {' '.join(args)} -> {err}")
    # Record the resolved stack so the run is reproducible from its own diagnostics, and fail here
    # (cheap) rather than inside a worker if the import is broken.
    v = subprocess.run(
        [sys.executable, "-c",
         "import torch, vllm; print(torch.__version__, torch.version.cuda, vllm.__version__)"],
        capture_output=True, text=True, timeout=600)
    DIAG["vllm_runtime"] = (v.stdout + v.stderr).strip()[-400:]
    dump_diag()
    if v.returncode != 0:
        raise RuntimeError(f"vLLM imported-version check failed: {DIAG['vllm_runtime']}")
    print(f"vLLM ready: {DIAG['vllm_runtime']}", flush=True)
    return {}


def load_vllm():
    """Build the engine. PYTHONPATH is already correct because the parent launched us with it."""
    from transformers import AutoTokenizer
    tok = AutoTokenizer.from_pretrained(MODEL_ID, revision=MODEL_REV)
    from vllm import LLM
    # enable_prefix_caching: the ~2,038-token instruction block is byte-identical on every report
    # (the report is appended LAST), so it is prefilled once rather than 4,407 times.
    llm = LLM(model=MODEL_ID, revision=MODEL_REV, tensor_parallel_size=TP,
              dtype="float16", max_model_len=MAX_LEN,
              gpu_memory_utilization=GPU_UTIL, enable_prefix_caching=True,
              enforce_eager=True, disable_custom_all_reduce=True,
              quantization=("awq" if QUANT == "awq" else None))
    DIAG["engine"] = "vllm"
    dump_diag()
    return tok, llm


def load_model():
    """Try the backends in order of install reliability and report which one worked."""
    import torch
    from transformers import AutoModelForCausalLM, AutoTokenizer
    tok = AutoTokenizer.from_pretrained(MODEL_ID, revision=MODEL_REV)
    attempts = []
    order = ([("nf4", "bitsandbytes"), ("awq", "gptqmodel"), ("awq", "autoawq")]
             if QUANT == "nf4" else
             [("awq", "gptqmodel"), ("awq", "autoawq"), ("nf4", "bitsandbytes")])
    if QUANT == "none":
        order = [("none", None)]
    for mode, pkg in order:
        try:
            if pkg:
                try:
                    __import__({"bitsandbytes": "bitsandbytes", "autoawq": "awq",
                                "gptqmodel": "gptqmodel"}[pkg])
                    ok, err = True, "already present"
                except Exception:
                    ok, err = pip_install(pkg)
                attempts.append({"mode": mode, "package": pkg, "install_ok": ok, "err": err})
                if not ok:
                    continue
            # torch_dtype governs the modules bitsandbytes does NOT quantize. Without it they
            # load in fp32, and for Qwen2.5-14B the 152k-vocab embedding plus lm_head is ~1.6B
            # parameters: 6.4 GB in fp32 against 3.2 GB in fp16. That difference alone is what
            # pushed the first run to 14.32 GB allocated on a 14.56 GB card and OOMed it -- the
            # 4-bit backend was working the whole time.
            # transformers 5.x renamed torch_dtype -> dtype, and the Kaggle image is on 5.0.0.
            # Passing the wrong one silently loses fp16 for the unquantised modules, which is the
            # exact 3.2 GB that OOMed the last run -- so pick by version and verify after loading.
            import transformers as _tf
            dt_key = "dtype" if int(_tf.__version__.split(".")[0]) >= 5 else "torch_dtype"
            kw = {"revision": MODEL_REV, dt_key: torch.float16,
                  "device_map": ({"": GPU} if GPU >= 0 else "auto")}
            if mode == "nf4":
                from transformers import BitsAndBytesConfig
                kw["quantization_config"] = BitsAndBytesConfig(
                    load_in_4bit=True, bnb_4bit_quant_type="nf4",
                    bnb_4bit_compute_dtype=torch.float16,
                    bnb_4bit_use_double_quant=True)
            m = AutoModelForCausalLM.from_pretrained(MODEL_ID, **kw)
            # Verify rather than trust: if the embedding came back fp32 the dtype argument did not
            # take, and the run will OOM a few GB later for a reason that looks like hardware.
            emb_dt = str(next(m.get_input_embeddings().parameters()).dtype)
            mem = torch.cuda.memory_allocated(GPU if GPU >= 0 else 0) / 1e9
            DIAG["embedding_dtype"] = emb_dt
            DIAG["weights_gb"] = round(mem, 2)
            print(f"loaded via {mode}: embeddings {emb_dt}, {mem:.2f} GB on card "
                  f"(dtype key {dt_key!r})", flush=True)
            if "float32" in emb_dt:
                raise RuntimeError(
                    f"embeddings loaded as {emb_dt}: the {dt_key!r} argument did not take on "
                    f"transformers {_tf.__version__}. For Qwen2.5-14B that is 3.2 GB of waste and "
                    f"the run will OOM later -- failing now, where the cause is legible.")
            if attempts:
                attempts[-1]["load_ok"] = True
            DIAG["backend_used"] = mode
            DIAG["backend_attempts"] = attempts
            return tok, m.eval()
        except Exception as e:
            if attempts:
                attempts[-1]["load_ok"] = False
                attempts[-1]["load_err"] = f"{type(e).__name__}: {str(e)[:300]}"
            DIAG["backend_attempts"] = attempts
            dump_diag()
            # a partially loaded model still holds the card; without this the next attempt OOMs
            # for a reason that has nothing to do with the next attempt
            import gc
            if "m" in locals():
                del m
            gc.collect()
            torch.cuda.empty_cache()
    raise RuntimeError(f"no 4-bit backend worked: {attempts}")


def main():
    t0 = time.time()
    WORK.mkdir(parents=True, exist_ok=True)
    print(f"stage {STAGE} | model {MODEL_ID} rev {MODEL_REV} | pass {PASS_NAME} | "
          f"engine {ENGINE}", flush=True)
    import torch
    print(f"torch {torch.__version__} | cuda {torch.cuda.is_available()} "
          f"| devices {torch.cuda.device_count()}", flush=True)
    for i in range(torch.cuda.device_count()):
        p = torch.cuda.get_device_properties(i)
        print(f"  gpu{i} {p.name} {p.total_memory / 1e9:.1f} GB", flush=True)
    import transformers
    try:
        transformers.utils.logging.set_verbosity_error()
        transformers.utils.logging.disable_progress_bar()
    except Exception:
        pass
    print(f"transformers {transformers.__version__}", flush=True)
    env = {"torch": torch.__version__, "transformers": transformers.__version__,
           "cuda": torch.cuda.is_available(), "n_gpu": torch.cuda.device_count(),
           "gpus": [torch.cuda.get_device_properties(i).name
                    for i in range(torch.cuda.device_count())]}
    for mod in ("awq", "vllm", "accelerate", "bitsandbytes", "optimum", "gptqmodel"):
        try:
            m = __import__(mod)
            env[mod] = getattr(m, "__version__", "present")
        except Exception:
            env[mod] = "MISSING"
        print(f"  {mod}: {env[mod]}", flush=True)
    dump_diag({"environment": env})

    comp = find_comp()
    train = pd.read_csv(comp / "train.csv")
    lp = None
    for d, _, fs in os.walk("/kaggle/input"):
        if "a1_language.csv" in fs:
            lp = Path(d) / "a1_language.csv"
            break
    if lp is None:
        raise FileNotFoundError("a1_language.csv not attached -- stratification needs it")
    lang = pd.read_csv(lp)[["StudyInstanceUID", "language"]]
    lang["StudyInstanceUID"] = lang.StudyInstanceUID.astype(str)
    ids, extra = select(STAGE, train, lang)
    if N_SHARD > 1:
        # deterministic, disjoint, and every worker sees the same ordering of `ids` beforehand
        ids = [s for i, s in enumerate(ids) if i % N_SHARD == SHARD]
        print(f"shard {SHARD}/{N_SHARD}: {len(ids)} of the selected reports", flush=True)
    rep = dict(zip(train.StudyInstanceUID.astype(str), train.Report))
    lmap = dict(zip(lang.StudyInstanceUID, lang.language.fillna("unassigned")))
    print(f"\n{len(ids)} reports selected | language mix: "
          f"{pd.Series([lmap.get(i, '?') for i in ids]).value_counts().to_dict()}", flush=True)

    dump_diag({"stage": STAGE, "model": MODEL_ID, "revision": MODEL_REV, "quant": QUANT,
               "n_selected": len(ids)})
    if ENGINE == "vllm":
        # The instruction block alone is ~2,038 tokens and a Greek report adds ~1,230 at p90, with
        # up to ~1,940 of output. A context that cannot hold that truncates Greek into invalidity --
        # the same failure the flat max_new cap already caused once, so it is checked, not assumed.
        need = 2100 + 1900 + MAX_NEW_CAP
        if MAX_LEN < need:
            raise SystemExit(f"EXTRACT_MAX_LEN={MAX_LEN} is too small: the prompt block is ~2,038 "
                             f"tokens, a long Greek report adds ~1,900, and the output budget goes "
                             f"to {MAX_NEW_CAP}. Need >= {need}.")
        # No fallback to transformers here, deliberately. probe4 fell back INTO an environment a
        # failed install had already modified, and reported a bitsandbytes ImportError that had
        # nothing to do with bitsandbytes. An engine failure must be legible as an engine failure.
        tok, model = load_vllm()
    else:
        tok, model = load_model()
    IS_VLLM = DIAG.get("engine", "").startswith("vllm")
    print(f"model loaded in {(time.time() - t0) / 60:.1f} min via "
          f"{DIAG.get('backend_used')}", flush=True)
    dump_diag({"model_load_minutes": (time.time() - t0) / 60})
    if SAVE_QUANT:
        # amortise the fp16 download: later kernels attach this output instead of re-downloading
        try:
            model.save_pretrained(WORK / "quantised", safe_serialization=True)
            tok.save_pretrained(WORK / "quantised")
            print("saved quantised weights to /kaggle/working/quantised", flush=True)
        except Exception as e:
            print(f"could not save quantised weights: {type(e).__name__}: {e}", flush=True)

    out, stats = [], {"valid": 0, "retried": 0, "failed": 0, "ev_ok": 0, "ev_total": 0}
    gen_t, gen_tok = 0.0, 0
    # Left padding: with a decoder-only model, right padding puts pad tokens between the prompt and
    # the first generated token, and every sequence in the batch answers a different question from
    # the one it was asked. This is the single easiest way to produce plausible nonsense at scale.
    tok.padding_side = "left"
    if tok.pad_token_id is None:
        tok.pad_token = tok.eos_token

    def budget_for(n_in):
        """Output allowance scaled to the input. Greek costs 1.16 chars/token against English's
        4.05, and the evidence is quoted verbatim, so a flat cap starves exactly one language."""
        return min(MAX_NEW_CAP, max(MAX_NEW, int(SCHEMA_TOKENS + EVIDENCE_FRACTION * n_in)))

    def build_texts(texts, retry):
        prompts = []
        for t in texts:
            msgs = build_prompt(t)
            if retry:
                msgs[-1]["content"] += ("\n\nYour previous answer was rejected: every evidence "
                                        "string must be copied EXACTLY from the report, character "
                                        "for character, in the report's own language. Re-answer.")
            prompts.append(tok.apply_chat_template(msgs, tokenize=False,
                                                   add_generation_prompt=True))
        return prompts

    def generate_vllm(texts, retry=False):
        """vLLM schedules sequences independently, so each gets its own output budget and there is
        no padding to get wrong."""
        from vllm import SamplingParams
        nonlocal gen_t, gen_tok
        prompts = build_texts(texts, retry)
        params = [SamplingParams(temperature=0.0, top_p=1.0,
                                 max_tokens=budget_for(len(tok(p_).input_ids)))
                  for p_ in prompts]
        g0 = time.time()
        # use_tqdm=False, not merely TQDM_DISABLE. vLLM's _run_engine computes
        # total_in_toks / pbar.format_dict["elapsed"] for its throughput line, and with tqdm
        # globally disabled that elapsed is 0 -- probe5 died on ZeroDivisionError after the engine
        # had loaded and started generating. Suppressing the bar at the call site avoids the
        # division entirely and keeps the log small, which is why tqdm was disabled in the first
        # place.
        outs = model.generate(prompts, params, use_tqdm=False)
        gen_t += time.time() - g0
        res = []
        for o in outs:
            c = o.outputs[0]
            gen_tok += len(c.token_ids)
            if c.finish_reason == "length":
                stats["truncated"] = stats.get("truncated", 0) + 1
            res.append(c.text)
        return res

    def generate_hf(texts, retry=False):
        prompts = []
        for t in texts:
            msgs = build_prompt(t)
            if retry:
                msgs[-1]["content"] += ("\n\nYour previous answer was rejected: every evidence "
                                        "string must be copied EXACTLY from the report, character "
                                        "for character, in the report's own language. Re-answer.")
            prompts.append(tok.apply_chat_template(msgs, tokenize=False,
                                                   add_generation_prompt=True))
        enc = tok(prompts, return_tensors="pt", padding=True).to(model.device)
        nonlocal gen_t, gen_tok
        # The output budget must scale with the INPUT, because evidence is quoted verbatim and
        # Greek costs 1.16 characters per token against English's 4.05 -- a Greek report is 694
        # median tokens where an English one is 262. A flat cap truncates the Greek JSON into
        # unparseability and marks all twelve cells invalid, which is exactly what a flat 900 did:
        # Greek schema validity 0.00, every other language 0.67-1.00.
        n_in = int(enc["input_ids"].shape[1])
        budget = budget_for(n_in)
        g0 = time.time()
        with torch.no_grad():
            o = model.generate(**enc, max_new_tokens=budget, do_sample=False,
                               temperature=None, top_p=None, top_k=None,
                               pad_token_id=tok.pad_token_id)
        gen_t += time.time() - g0
        new = o[:, enc["input_ids"].shape[1]:]
        gen_tok += int((new != tok.pad_token_id).sum())
        used = int((new != tok.pad_token_id).sum(1).max())
        if used >= budget:
            # hit the ceiling: at least one answer is truncated and will parse as invalid
            stats["truncated"] = stats.get("truncated", 0) + 1
            print(f"    TRUNCATED: used {used} of {budget} (input {n_in})", flush=True)
        return tok.batch_decode(new, skip_special_tokens=True)

    generate = generate_vllm if IS_VLLM else generate_hf

    def batch_invariance_check():
        """The same report, alone and inside a padded batch, must give the same statuses."""
        if BATCH < 2 or len(ids) < 2:
            print("batch-invariance check skipped (batch size 1)", flush=True)
            return
        long_i = max(range(len(ids)), key=lambda i: len(norm(rep.get(ids[i], ""))))
        short_i = min(range(len(ids)), key=lambda i: len(norm(rep.get(ids[i], ""))))
        if long_i == short_i:
            return
        a = norm(rep.get(ids[short_i], ""))[:6000]
        b = norm(rep.get(ids[long_i], ""))[:6000]
        # padding only bites when the batch members have very different lengths
        alone = parse_json(generate([a])[0])
        batched = parse_json(generate([a, b])[0])
        if alone is None or batched is None:
            print("batch-invariance check INCONCLUSIVE: one generation did not parse", flush=True)
            DIAG["batch_invariance"] = "inconclusive"
            return
        ca = validate(alone, a)[0] or {}
        cb = validate(batched, a)[0] or {}
        sa = {f: ca.get(f, {}).get("status") for f in LAB}
        sb = {f: cb.get(f, {}).get("status") for f in LAB}
        same = sum(sa[f] == sb[f] for f in LAB)
        DIAG["batch_invariance"] = {"statuses_equal": same, "of": len(LAB),
                                    "alone": sa, "batched": sb,
                                    "len_short": len(a), "len_long": len(b)}
        dump_diag()
        print(f"batch-invariance check: {same}/{len(LAB)} statuses identical alone vs batched "
              f"(report lengths {len(a)} and {len(b)})", flush=True)
        if same < len(LAB) - 2:
            raise RuntimeError(
                f"batching changed the answer: only {same}/{len(LAB)} statuses match when the same "
                f"report is generated inside a padded batch (padding_side="
                f"{tok.padding_side!r}, pad_token_id={tok.pad_token_id}). Greedy decoding must be "
                f"deterministic, so this means the padded batch is not asking the question it "
                f"looks like it is asking -- refusing to extract 4,407 reports this way.")

    batch_invariance_check()
    done = 0
    for b0 in range(0, len(ids), BATCH):
        chunk = ids[b0:b0 + BATCH]
        texts = [norm(rep.get(s, ""))[:6000] for s in chunk]
        got = {}
        for attempt in (0, 1):
            todo = [i for i in range(len(chunk)) if i not in got]
            if not todo:
                break
            if attempt:
                stats["retried"] += len(todo)
            for i, raw in zip(todo, generate([texts[i] for i in todo], retry=bool(attempt))):
                obj = parse_json(raw)
                if obj is None:
                    continue
                cells, problems, rl = validate(obj, texts[i])
                if cells and not any("not a substring" in p for p in problems):
                    got[i] = (cells, rl)
                elif cells and attempt:
                    got[i] = (cells, rl)          # second attempt: keep it and flag the cells
        for i, sid in enumerate(chunk):
            if i in got:
                cells, rl = got[i]
                stats["valid"] += 1
            else:
                stats["failed"] += 1
                cells, rl = {f: {"status": "invalid", "severity": "unspecified", "evidence": "",
                                 "compartment": None, "evidence_ok": False,
                                 "acl_substatus": "unspecified" if f == "ACL" else ""}
                             for f in LAB}, ""
            for f in LAB:
                c = cells[f]
                if c["status"] in ("positive", "negative", "uncertain"):
                    stats["ev_total"] += 1
                    stats["ev_ok"] += bool(c["evidence_ok"])
                out.append({"StudyInstanceUID": sid, "language": lmap.get(sid, "?"),
                            "report_language_llm": rl, "finding": f, **c})
            done += 1
        el = time.time() - t0
        print(f"  {done}/{len(ids)} | {el / 60:.1f} min | "
              f"{gen_tok / max(gen_t, 1e-9):.1f} tok/s | "
              f"{done / max(el, 1e-9) * 3600:.0f} reports/h | eta "
              f"{el / done * (len(ids) - done) / 60:.1f} min", flush=True)
        dump_diag({"progress": f"{done}/{len(ids)}", "reports_per_hour": done / max(el, 1e-9) * 3600,
                   "tokens_per_second": gen_tok / max(gen_t, 1e-9), "stats": dict(stats)})

    df = pd.DataFrame(out)
    tag = f"_s{SHARD}" if N_SHARD > 1 else ""
    df.to_csv(WORK / f"extract_{PASS_NAME}_{STAGE}{tag}.csv", index=False)
    per_lang = (df.groupby("language")
                  .agg(cells=("status", "size"),
                       invalid=("status", lambda s: (s == "invalid").mean()),
                       ev_ok=("evidence_ok", "mean")).round(4))
    print(f"\nschema validity {stats['valid']}/{len(ids)} reports "
          f"({stats['valid'] / len(ids):.3f}) | retried {stats['retried']} | "
          f"failed {stats['failed']}")
    print(f"evidence-substring rate {stats['ev_ok']}/{stats['ev_total']} "
          f"({stats['ev_ok'] / max(stats['ev_total'], 1):.3f})")
    print(f"\nper language:\n{per_lang.to_string()}")
    if extra:
        print("\nKNOWN-ANSWER CHECKS (pre-specified answers, not scored against C or the host):")
        ka = {}
        for name, spec in extra.items():
            row = df[(df.StudyInstanceUID == spec["study"]) & (df.finding == spec["finding"])]
            got = str(row.status.iloc[0]) if len(row) else "MISSING"
            ev_ok = bool(row.evidence_ok.iloc[0]) if len(row) else False
            ok = (got == spec["expected_status"]) and ev_ok
            ka[name] = {"expected": spec["expected_status"], "got": got, "evidence_ok": ev_ok,
                        "pass": ok, "rule": spec["rule"]}
            print(f"  {'PASS' if ok else 'FAIL'}  {name:<24} {spec['finding']:<10} "
                  f"expected {spec['expected_status']:<9} got {got:<13} evidence_ok={ev_ok}")
            if not ok:
                print(f"        rule under test: {spec['rule']}")
        n_pass = sum(v["pass"] for v in ka.values())
        print(f"  {n_pass}/{len(ka)} known-answer checks passed")
        extra = {"cases": extra, "results": ka, "n_pass": n_pass, "n_total": len(ka)}
    acl_sub = (df[df.finding == "ACL"].acl_substatus.fillna("").value_counts().to_dict())
    print(f"\nACL sub-status distribution: {acl_sub}")
    rate = len(ids) / max(time.time() - t0, 1e-9)
    # N_SHARD workers run concurrently on the same kernel, so the wall-clock cost of a full pass is
    # the per-worker rate times the number of workers
    full_h = 4407 / max(rate * N_SHARD, 1e-9) / 3600
    print(f"\nthroughput {rate * 3600:.0f} reports/hour | {gen_tok / max(gen_t, 1e-9):.1f} tok/s")
    print(f"PROJECTED full single pass over 4,407 reports: {full_h:.2f} kernel-hours "
          f"({2 * full_h:.2f} for two passes) at batch {BATCH} x {N_SHARD} worker(s)")
    if 2 * full_h > 6:
        print(f"OVER BUDGET: A7 says report before launching if two passes exceed 6 GPU-hours. "
              f"Projection is {2 * full_h:.2f}.")
    json.dump({"stage": STAGE, "pass": PASS_NAME, "model": MODEL_ID, "revision": MODEL_REV,
               "seed": SEED, "n_reports": len(ids), "stats": stats,
               "batch": BATCH, "gpu": GPU, "shard": SHARD, "n_shard": N_SHARD,
               "max_new_tokens": MAX_NEW,
               "reports_per_hour": rate * 3600, "tokens_per_second": gen_tok / max(gen_t, 1e-9),
               "projected_full_pass_gpu_hours": full_h,
               "projected_two_passes_gpu_hours": 2 * full_h,
               "per_language": per_lang.to_dict(), "known_answer_cases": extra,
               "acl_substatus": acl_sub, "acl_substatus_binarise": ACL_SUB_BINARISE,
               "minutes": (time.time() - t0) / 60},
              open(WORK / f"extract_{PASS_NAME}_{STAGE}{tag}_summary.json", "w"), indent=1)
    print(f"\nwrote extract_{PASS_NAME}_{STAGE}{tag}.csv")


def vllm_cleanup():
    """Remove the staged runtime from /kaggle/working.

    It is several GB, it counts against the ~20 GB output cap, and it makes `kernels output` crawl.
    probe4's FAILED run left it behind, which is why this is in a finally and not on the happy
    path -- the run you most need the diagnostics from is the one that broke."""
    if ENGINE != "vllm":
        return
    import shutil
    for d in ("vllm-staged", "vllm-runtime-overlay", "kaggle-vllm-cache"):
        shutil.rmtree(WORK / d, ignore_errors=True)
    print("removed the vLLM staging directories from /kaggle/working", flush=True)


def run_parent():
    """Stage what the workers need, launch them with the right environment, then merge.

    For vLLM this is not an optimisation but the only way it works: PYTHONPATH and LD_LIBRARY_PATH
    have to be set before the interpreter starts, and the staged wheel is not importable without
    them."""
    import subprocess
    WORK.mkdir(parents=True, exist_ok=True)
    child_env = {}
    if ENGINE == "vllm":
        child_env = vllm_bootstrap()
        dump_diag()
    # Fetch the weights ONCE here. Two workers starting together would otherwise race on the same
    # Hugging Face cache directory; the hub's file locks make that correct but serial, and a failure
    # mid-download leaves a partial cache that the second worker inherits.
    t_dl = time.time()
    try:
        from huggingface_hub import snapshot_download
        path = snapshot_download(MODEL_ID, revision=MODEL_REV,
                                 allow_patterns=["*.json", "*.safetensors", "*.txt", "*.model"])
        print(f"weights cached in {(time.time() - t_dl) / 60:.1f} min at {path}", flush=True)
        dump_diag({"download_minutes": (time.time() - t_dl) / 60, "weights_path": str(path)})
    except Exception as e:
        # not fatal: each worker can still download for itself, just more slowly
        print(f"pre-download failed ({type(e).__name__}: {e}); workers will fetch individually",
              flush=True)
        dump_diag({"predownload_error": f"{type(e).__name__}: {e}"})
    procs = []
    for i in range(N_SHARD):
        env = dict(os.environ)
        env.update(child_env)          # empty for vLLM now: it is a normal site-packages install
        env.update({"EXTRACT_SHARD": str(i), "EXTRACT_N_SHARD": str(N_SHARD),
                    # vLLM owns both cards through tensor parallelism; it must not be pinned to one
                    "EXTRACT_GPU": ("-1" if ENGINE == "vllm" else str(i)),
                    "EXTRACT_ENGINE": ENGINE, "EXTRACT_TP": str(TP),
                    "EXTRACT_GPU_UTIL": str(GPU_UTIL), "EXTRACT_MAX_LEN": str(MAX_LEN),
                    "EXTRACT_STAGE": STAGE, "EXTRACT_PASS": PASS_NAME,
                    "EXTRACT_MODEL": MODEL_ID, "EXTRACT_REV": MODEL_REV,
                    "EXTRACT_QUANT": QUANT, "EXTRACT_BATCH": str(BATCH),
                    "EXTRACT_MAX_NEW": str(MAX_NEW)})
        log = io.open(WORK / f"worker{i}.log", "w", encoding="utf-8", errors="replace")
        print(f"launching worker {i} on gpu {i}", flush=True)
        procs.append((i, subprocess.Popen([sys.executable, os.path.abspath(__file__)],
                                          env=env, stdout=log, stderr=subprocess.STDOUT), log))
    codes = []
    for i, pr, log in procs:
        rc = pr.wait()
        log.close()
        codes.append((i, rc))
        print(f"worker {i} exited {rc}", flush=True)
    dump_diag({"worker_exit_codes": dict(codes)})
    bad = [i for i, rc in codes if rc != 0]
    if bad:
        # a partial corpus is worse than no corpus: it would be scored as if it were complete
        for i in bad:
            tail = io.open(WORK / f"worker{i}.log", encoding="utf-8",
                           errors="replace").read()[-2000:]
            print(f"\n--- worker {i} tail ---\n{tail}", flush=True)
        raise RuntimeError(f"workers {bad} failed; refusing to merge a partial extraction")
    parts = [WORK / (f"extract_{PASS_NAME}_{STAGE}"
                     + (f"_s{i}" if N_SHARD > 1 else "") + ".csv") for i in range(N_SHARD)]
    missing = [q.name for q in parts if not q.exists()]
    if missing:
        raise RuntimeError(f"missing shard output: {missing}")
    df = pd.concat([pd.read_csv(q) for q in parts], ignore_index=True)
    n_expected = df.StudyInstanceUID.nunique() * len(LAB)
    if len(df) != n_expected:
        raise RuntimeError(f"merged {len(df)} rows for {df.StudyInstanceUID.nunique()} studies; "
                           f"expected {n_expected} -- the shards overlap or a study is short")
    df.to_csv(WORK / f"extract_{PASS_NAME}_{STAGE}.csv", index=False)
    subs = []
    for i in range(N_SHARD):
        q = WORK / (f"extract_{PASS_NAME}_{STAGE}"
                    + (f"_s{i}" if N_SHARD > 1 else "") + "_summary.json")
        if q.exists():
            subs.append(json.load(open(q)))
    rate = sum(x.get("reports_per_hour", 0) for x in subs)
    full_h = 4407 / max(rate, 1e-9)
    print(f"\nmerged {len(df)} rows / {df.StudyInstanceUID.nunique()} studies")
    print(f"combined throughput {rate:.0f} reports/hour over {N_SHARD} worker(s)")
    print(f"PROJECTED full single pass: {full_h:.2f} kernel-hours ({2 * full_h:.2f} for two passes)")
    if 2 * full_h > 6:
        print(f"OVER BUDGET: A7 says report before launching if two passes exceed 6 GPU-hours. "
              f"Projection is {2 * full_h:.2f}.")
    json.dump({"shards": subs, "combined_reports_per_hour": rate,
               "projected_full_pass_hours": full_h,
               "projected_two_passes_hours": 2 * full_h,
               "n_rows": len(df), "n_studies": int(df.StudyInstanceUID.nunique())},
              open(WORK / f"extract_{PASS_NAME}_{STAGE}_merged_summary.json", "w"), indent=1)


if __name__ == "__main__":
    try:
        # EXTRACT_SHARD unset + more than one shard requested = this is the parent
        if ENGINE == "vllm" and N_SHARD > 1:
            raise SystemExit("vLLM uses tensor parallelism across both GPUs; set EXTRACT_N_SHARD=1. "
                             "Two vLLM workers would each try to claim both cards.")
        # vLLM needs the parent even at one shard: the staging environment can only be applied to a
        # process that has not started yet.
        if (N_SHARD > 1 or ENGINE == "vllm") and "EXTRACT_SHARD" not in os.environ:
            try:
                run_parent()
            finally:
                vllm_cleanup()
        else:
            main()
        dump_diag({"status": "ok"})
    except Exception as e:
        import traceback
        dump_diag({"status": "failed", "error": f"{type(e).__name__}: {e}",
                   "traceback": traceback.format_exc()[-3000:]})
        raise
